(7475287, 1187661, 94815, '<td valign="top">Good use of tilt/shift technique to draw attention to a subject instead of silly contrivances.</td>', 'Good use of tilt/shift technique to draw attention to a subject instead of silly contrivances.', '2016-09-22 22:31:56.000000', NULL, 1),
