(7475294, 1187666, 94815, '<td valign="top">Brilliantly executed and attention grabbing subject. My top pick as the best of the few to see past the "miniature town" silliness. 10</td>', 'Brilliantly executed and attention grabbing subject. My top pick as the best of the few to see past the "miniature town" silliness. 10', '2016-09-22 22:45:08.000000', NULL, 1),
(7475295, 1187292, 94815, '<td valign="top">Smart use of foreground/background blur to enhance attention to the subject. This guy seems especially sure of himself. 9</td>', 'Smart use of foreground/background blur to enhance attention to the subject. This guy seems especially sure of himself. 9', '2016-09-22 22:45:40.000000', NULL, 1),
(7475296, 1187679, 94815, '<td valign="top">Bring it on. This stands out as the only image in the challenge with some real ambiguity to make us work a bit beyond the initial impression of noir-ish lake-scape. Struggling back to something specific I think the whatzit might be a bird with a rather robotic posture. Fun and an 8.</td>', 'Bring it on. This stands out as the only image in the challenge with some real ambiguity to make us work a bit beyond the initial impression of noir-ish lake-scape. Struggling back to something specific I think the whatzit might be a bird with a rather robotic posture. Fun and an 8.', '2016-09-22 22:51:33.000000', NULL, 1),
(7475299, 1187675, 94815, '<td valign="top">Smart use of the tilt/shirt technique to take an interesting if not strong landscape and turn it into something rather magical. 7</td>', 'Smart use of the tilt/shirt technique to take an interesting if not strong landscape and turn it into something rather magical. 7', '2016-09-22 22:55:44.000000', NULL, 1),
(7475306, 1187485, 94815, '<td valign="top">I chuckled at this and thanks for the parody among a boring set of lookalike miniature towns. I especially love what you do with the grown ups dissolving abruptly into the minitown foreground. A 7 for thinking beyond cliché.</td>', 'I chuckled at this and thanks for the parody among a boring set of lookalike miniature towns. I especially love what you do with the grown ups dissolving abruptly into the minitown foreground. A 7 for thinking beyond cliché.', '2016-09-22 23:04:01.000000', NULL, 1),
(7475307, 1187271, 94815, '<td valign="top">In spite of the title, I enjoy this image for the way you''ve used the tilt/shift technique (or not) to dramatically blur the fore/background to focus on the frieze of random strollers and the bike. Nice work. 7</td>', 'In spite of the title, I enjoy this image for the way you''ve used the tilt/shift technique (or not) to dramatically blur the fore/background to focus on the frieze of random strollers and the bike. Nice work. 7', '2016-09-22 23:05:09.000000', NULL, 1),
(7475308, 1187667, 94815, '<td valign="top">So many mini-town landscapes but this one stood out for some individuality. 6</td>', 'So many mini-town landscapes but this one stood out for some individuality. 6', '2016-09-22 23:06:12.000000', NULL, 1),
(7475310, 1187672, 94815, '<td valign="top">Looks like shift used in the old fashioned way, e.g. properly. 6</td>', 'Looks like shift used in the old fashioned way, e.g. properly. 6', '2016-09-22 23:07:15.000000', NULL, 1),
(7475313, 1187683, 94815, '<td valign="top">Creative twist on the topic and thanks for not another mini-town lookalike. 6</td>', 'Creative twist on the topic and thanks for not another mini-town lookalike. 6', '2016-09-22 23:08:32.000000', NULL, 1),
(7475320, 1187671, 94815, '<td valign="top">I''m enjoying the river and receding bridges, but what an awful thing to do to Paris. For that, its a standout and gets a 6 for terribleness.</td>', 'I''m enjoying the river and receding bridges, but what an awful thing to do to Paris. For that, its a standout and gets a 6 for terribleness.', '2016-09-22 23:17:03.000000', NULL, 1),
(7475321, 1187267, 94815, '<td valign="top">This looks like the stairs leading town to the lower falls in Niagara Falls. If not, a good imitation with tilt/shift blur used effectively to enhance the misty air soaking the stair-climbers. 6</td>', 'This looks like the stairs leading town to the lower falls in Niagara Falls. If not, a good imitation with tilt/shift blur used effectively to enhance the misty air soaking the stair-climbers. 6', '2016-09-22 23:18:24.000000', NULL, 1),
